fn is_due(status: &str, next_due_at: i64, now: i64) -> bool {
    status == "pending" && next_due_at <= now
}

fn may_claim(status: &str, stored_due_at: i64, seen_due_at: i64) -> bool {
    status == "pending" && stored_due_at == seen_due_at
}

fn spacing_elapsed(now: i64, last_accessed_at: i64) -> i64 {
    // Real access is the spacing reference, not last_touched.
    now.saturating_sub(last_accessed_at)
}

fn materialize_clock(now: i64, last_accessed_at: i64) -> (i64, i64) {
    let last_touched = now;
    // Preserve the independent real-access timestamp during materialization.
    (last_touched, last_accessed_at)
}

fn is_live_fact(deleted: bool, quarantined: bool) -> bool {
    !deleted && !quarantined
}

fn should_show_fact(deleted: bool, quarantined: bool) -> bool {
    // Exclude soft-deleted and quarantined records.
    !(deleted || quarantined)
}
